  function recalculateStandings2(db, series = "honor") {
    if (!db.clubs || !db.matches) return;
    const seriesMatches = db.matches.filter((m) => m.series === series && m.status === "finalizado");
    const statsMap = {};
    db.clubs.forEach((c) => {
      statsMap[c.id] = {
        clubId: c.id,
        clubName: c.name,
        pj: 0,
        pg: 0,
        pe: 0,
        pp: 0,
        gf: 0,
        gc: 0,
        dg: 0,
        pts: 0
      };
    });
    seriesMatches.forEach((m) => {
      const h = statsMap[m.homeClubId];
      const a = statsMap[m.awayClubId];
      if (!h || !a) return;
      h.pj += 1;
      a.pj += 1;
      h.gf += m.homeScore || 0;
      h.gc += m.awayScore || 0;
      a.gf += m.awayScore || 0;
      a.gc += m.homeScore || 0;
      if (m.homeScore > m.awayScore) {
        h.pg += 1;
        h.pts += 3;
        a.pp += 1;
      } else if (m.homeScore < m.awayScore) {
        a.pg += 1;
        a.pts += 3;
        h.pp += 1;
      } else {
        h.pe += 1;
        h.pts += 1;
        a.pe += 1;
        a.pts += 1;
      }
      h.dg = h.gf - h.gc;
      a.dg = a.gf - a.gc;
    });
    const sorted = Object.values(statsMap).sort((a, b) => {
      if (b.pts !== a.pts) return b.pts - a.pts;
      if (b.dg !== a.dg) return b.dg - a.dg;
      return b.gf - a.gf;
    });
    sorted.forEach((row, idx) => {
      row.pos = idx + 1;
    });
    if (!db.standings) db.standings = {};
    db.standings[series] = sorted;
  }
