    if (finalName === "Personalizado...") {
      finalName = "Nuevo Sponsor";
    }
    const logoDataUrl = resolveBrandLogo(finalName);
    const id = `sponsor-${Date.now()}`;
    db.sponsors.push({ id, name: finalName, logoBase64: logoDataUrl });
