    const pillH = 34;
    const pillX = (w - pillW) / 2;
    const pillY = 46;
    roundRect(ctx, pillX, pillY, pillW, pillH, 17);
    ctx.fillStyle = "rgba(255, 255, 255, 0.08)";
    ctx.fill();
    ctx.strokeStyle = theme.accent;
