    ctx.strokeStyle = "rgba(255, 255, 255, 0.12)";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(w * 0.15, 204);
    ctx.lineTo(w * 0.45, 204);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(w * 0.55, 204);
    ctx.lineTo(w * 0.85, 204);
